<template><div><h3>Tracks</h3><div v-for='t in tracks' :key='t.id' style='border:1px solid #eee;padding:8px;margin-bottom:6px;'><strong>{{ t.name }}</strong><ul><li v-for='take in t.takes' :key='take.id'><button @click='play(take)'>▶</button> {{ take.name }}</li></ul></div></div></template><script setup lang='ts'>import { useProjectStore } from '../stores/project'; const project=useProjectStore(); const tracks=project.tracks as any; function play(take:any){ new Audio(take.url).play(); }</script>